%%
datevec(TIK_rd.Time(1))
datevec(TIK_rd.Time(end))
%prctile(TIK_rd.U_S,[5 50 95])
plotFigControl(TIK_rd,TIK_st.name); %[output:3efc2429] %[output:72a5a9d0] %[output:164d75e1] %[output:49e62963] %[output:34e0ed08] %[output:08611148] %[output:355e8bf6] %[output:7d627fe8] %[output:30184366]
