lambdaAE=[467;530;660]*ones(1,4);
lambdaAE7=[370 470 520 590 660 880 950];
TIK_cal=compute_exp_SSA(TIK_rd,lambdaSC, lambdaAE); %[output:46cd265c] %[output:622b0ff7] %[output:07a2e5fd] %[output:6a74be54] %[output:2e8df6ea] %[output:0245ce0a] %[output:7c8b70f4] %[output:41f86276] %[output:9f9da52a] %[output:9ae26243] %[output:44148c75] %[output:6e1210f5] %[output:304519d1] %[output:14333792] %[output:1316ef73] %[output:6f0c83e5] %[output:402edf35] %[output:0f5664dc] %[output:3e8d8d8a] %[output:18c29dc8] %[output:78c2363d] %[output:55c1c2e3] %[output:71f6b1a1] %[output:33014ca8] %[output:7fe8eb46] %[output:18809efe] %[output:3a9db187] %[output:93a25db5] %[output:22965aaf] %[output:43030857] %[output:4b4c1680] %[output:7685029b] %[output:234f83f5] %[output:7cffc249] %[output:0a76f1ca]
